function brandBar(onDark = false): string {
	return `<div class="brand${onDark ? ' on-dark' : ''}">
    <img class="brand-mark" src="data:image/svg+xml;base64,${LOGO_SVG_B64}" alt="">
    <div class="brand-name">SkySEO</div>
    <div class="brand-sub">· разбор выдачи Яндекса</div>
  </div>`
}

/** Главный запрос — тот, где сайт выше всех: по нему предложение звучит убедительнее. */
function pickMainKeyword(keywords: ReportKeyword[]): ReportKeyword | null {
	const withPos = keywords.filter(k => k.position != null && k.competitors.length > 0)
	if (!withPos.length) return keywords[0] ?? null
	return withPos.reduce((a, b) => ((a.position ?? 99) <= (b.position ?? 99) ? a : b))
}

/** Лестница: этажи со скобками сверху вниз, внизу — жёлтая строка «вы здесь». */
function ladder(k: ReportKeyword): string {
	const own = k.position ?? 99
	const blocks = TIERS.filter(t => t.from < own)
		.map(tier => {
			const rivals = k.competitors.filter(c => c.position >= tier.from && c.position <= Math.min(tier.to, own - 1))
			if (!rivals.length) return ''
			return `
      <div class="tier">
        ${brace(C.periwinkleDeep)}
        <div class="tier-body">
          <div class="tier-head">
            <div>
              <span class="tier-title">${tier.title}</span>
              <span class="tier-range">· места ${tier.from}–${Math.min(tier.to, own - 1)}</span>
            </div>
            ${tier.note ? `<span class="tier-note">${tier.note}</span>` : ''}
          </div>
          <div class="tier-hint">${tier.hint}</div>
          <div class="rivals">${rivals.map(rivalChip).join('')}</div>
        </div>
      </div>`
		})
		.join('')

	return `${blocks}
    <div class="you-row">
      <span>Ваш сайт</span>
      <span>${own} место</span>
    </div>`
}

function rivalChip(c: ReportCompetitor): string {
	return `<span class="rival"><b>${c.position}</b>${esc(c.domain)}</span>`
}
